var i=`0504-qidreh`;var o=`world-0504`;var t=`PS`;var a=`western-asia`;var r=4;var s=78;var d={en:`Qidreh`,ua:`Кідре`};var l={en:`A traditional dish from Palestine, centered on lamb, yellow onion, basmati rice, canned chickpeas. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Палестина. Основні складники: ягнятина, жовта цибуля, рис басматі, консервований нут. Домашній варіант із кількостями продуктів за етапами приготування.`};var c=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 14 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 14 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:14,i:[[`lamb`,700,`g`],[`yellow-onion`,150,`g`],[`unsalted-butter`,50,`g`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 28 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 28 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:28,i:[[`basmati-rice`,460,`g`],[`chicken-stock`,840,`ml`],[`canned-chickpeas`,220,`g`],[`ground-cinnamon`,5,`g`],[`ground-cardamom`,5,`g`]]},{en:`Roast in a preheated 190°C oven for about 32 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 32 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:32,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`almond`,65,`g`]]}];var u={slug:i,id:o,country:`PS`,region:a,servings:4,minutes:78,title:d,text:l,steps:c};export{t as country,u as default,o as id,s as minutes,a as region,r as servings,i as slug,c as steps,l as text,d as title};